mapper.select:
SELECT r.*, m.display_name AS owner_display_name, d.config_json, d.config_hash, d.validation_json FROM resource r JOIN enterprise_member m ON m.enterprise_id = r.enterprise_id AND m.user_id = r.owner_user_id LEFT JOIN resource_draft d ON d.enterprise_id = r.enterprise_id AND d.resource_id = r.id WHERE r.enterprise_id = #{enterprise} AND r.id = #{id}
AND r.deleted_at IS NULL
FOR UPDATE
